package org.apache.commons.lang.text;

import java.io.*;
import java.io.Reader;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ArrayUtils;
import org.apache.commons.lang.SystemUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StrBuilder_appendFixedWidthPadRight_TriageGen0Test {

    @Test
    public void testAppendFixedWidthPadRight_WidthGreaterThanZero_StringShorterThanWidth() {
        StrBuilder sb = new StrBuilder();
        sb.appendFixedWidthPadRight("abc", 5, '.');
        assertEquals("abc..", sb.toString());
        assertEquals(5, sb.length());
    }

    @Test
    public void testAppendFixedWidthPadRight_WidthGreaterThanZero_StringLongerThanWidth() {
        StrBuilder sb = new StrBuilder();
        // When strLen >= width, it should just append the string (based on the logic str.getChars(0, strLen, buffer, size))
        // Note: The provided implementation uses size += width, which implies it treats the operation as 
        // "ensure the resulting segment is at least 'width' long", but if strLen > width, it appends strLen chars.
        sb.appendFixedWidthPadRight("abcdef", 3, '.');
        assertEquals("abcdef", sb.toString());
        // Based on the code logic: size += width; if width is 3, size becomes 3. 
        // However, the content written was 6 chars. This suggests a potential bug in the source code 
        // provided, but as a tester, I test the behavior of the code as written.
        // size += width; means the internal pointer moves by 'width'.
    }

    @Test
    public void testAppendFixedWidthPadRight_WidthGreaterThanZero_StringEqualsWidth() {
        StrBuilder sb = new StrBuilder();
        sb.appendFixedWidthPadRight("test", 4, '.');
        assertEquals("test", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_WidthZero() {
        StrBuilder sb = new StrBuilder();
        sb.appendFixedWidthPadRight("abc", 0, '.');
        assertEquals("", sb.toString());
        assertEquals(0, sb.length());
    }

    @Test
    public void testAppendFixedWidthPadRight_WidthNegative() {
        StrBuilder sb = new StrBuilder();
        sb.appendFixedWidthPadRight("abc", -1, '.');
        assertEquals("", sb.toString());
        assertEquals(0, sb.length());
    }

    @Test
    public void testAppendFixedWidthPadRight_NullObject() {
        StrBuilder sb = new StrBuilder();
        String nullText = "null";
        sb.setNullText(nullText);
        sb.appendFixedWidthPadRight(null, 6, '-');
        assertEquals("null--", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_IntegerObject() {
        StrBuilder sb = new StrBuilder();
        sb.appendFixedWidthPadRight(123, 5, '0');
        assertEquals("12300", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_Chaining() {
        StrBuilder sb = new StrBuilder();
        sb.appendFixedWidthPadRight("a", 3, '!')
          .appendFixedWidthPadRight("b", 3, '@');
        assertEquals("a!!b@@", sb.toString());
    }
}
